#include <c10/cuda/CUDAStream.h>
#include <math.h>

#include <cute/tensor.hpp>

using namespace cute;

constexpr int BLOCK_N        = 32;
constexpr int ROWS_PER_BLOCK = 8;
constexpr int THREADS        = ROWS_PER_BLOCK * 32;
constexpr int MAX_EPL        = 64; // supports head_dim up to 2048 (2048/32=64)

template <int EPL_CT>
__global__ void flash_attn_kernel(
    const half* __restrict__ Qg,
    const half* __restrict__ Kg,
    const half* __restrict__ Vg,
    half* __restrict__ Og,
    int B, int H, int N, int D, float scale, int block_n)
{
  extern __shared__ __align__(16) unsigned char smem_raw[];
  half* sK_ptr = reinterpret_cast<half*>(smem_raw);
  half* sV_ptr = sK_ptr + (size_t)block_n * D;
  // CuTe shared-memory tensors for the K/V tile: shape (block_n, D) -- block_n is a
  // runtime-selected effective K/V tile length (<= BLOCK_N) chosen so that the
  // shared-memory footprint fits within the device's actual dynamic shared memory limit.
  auto sK_t = make_tensor(make_smem_ptr(sK_ptr), make_shape(block_n, D), make_stride(D, 1));
  auto sV_t = make_tensor(make_smem_ptr(sV_ptr), make_shape(block_n, D), make_stride(D, 1));
  int bh = blockIdx.y;      // combined batch*head index
  int b  = bh / H;
  int h  = bh % H;

  const int64_t head_stride = (int64_t)N * D;
  const half* Qptr = Qg + ((int64_t)b * H + h) * head_stride;
  const half* Kptr = Kg + ((int64_t)b * H + h) * head_stride;
  const half* Vptr = Vg + ((int64_t)b * H + h) * head_stride;
  half*       Optr = Og + ((int64_t)b * H + h) * head_stride;

  // CuTe global-memory tensors: shape (N, D)
  auto mQ = make_tensor(make_gmem_ptr(Qptr), make_shape(N, D), make_stride(D, 1));
  auto mK = make_tensor(make_gmem_ptr(Kptr), make_shape(N, D), make_stride(D, 1));
  auto mV = make_tensor(make_gmem_ptr(Vptr), make_shape(N, D), make_stride(D, 1));
  auto mO = make_tensor(make_gmem_ptr(Optr), make_shape(N, D), make_stride(D, 1));

  int tid     = threadIdx.x;
  int warp_id = tid / 32;
  int lane    = tid % 32;
  int row     = blockIdx.x * ROWS_PER_BLOCK + warp_id;
  bool row_valid = row < N;

  constexpr int ARR_SZ = (EPL_CT > 0) ? EPL_CT : MAX_EPL;
  int epl = (EPL_CT > 0) ? EPL_CT : (D / 32); // elements-per-lane (compile-time constant when EPL_CT>0)
  alignas(16) half  q_reg[ARR_SZ];
  float o_reg[ARR_SZ];
  #pragma unroll
  for (int i = 0; i < ARR_SZ; ++i) o_reg[i] = 0.0f;
  if (row_valid) {
    int i = 0;
    for (; i + 1 < epl; i += 2) {
      const half2* qptr2 = reinterpret_cast<const half2*>(&mQ(row, lane * epl + i));
      *reinterpret_cast<half2*>(&q_reg[i]) = *qptr2;
    }
    for (; i < epl; ++i) {
      q_reg[i] = mQ(row, lane * epl + i);
    }
  }
  float m_i = -INFINITY;
  float l_i = 0.0f;
  for (int n0 = 0; n0 < N; n0 += block_n) {
    int tile_n = min(block_n, N - n0);
    // D is guaranteed divisible by 32; use 128-bit (float4) vectorized transfers
    // when possible (D % 8 == 0) to cut instruction count and improve global
    // memory transaction efficiency, falling back to half2 otherwise.
    int total_elems = tile_n * D;
    if ((D & 7) == 0) {
      int total_quads = total_elems / 8;
      for (int idx = tid; idx < total_quads; idx += THREADS) {
        int idx8 = idx * 8;
        int nn = idx8 / D;
        int dd = idx8 - nn * D;
        const float4* kptr4 = reinterpret_cast<const float4*>(&mK(n0 + nn, dd));
        const float4* vptr4 = reinterpret_cast<const float4*>(&mV(n0 + nn, dd));
        *reinterpret_cast<float4*>(&sK_t(nn, dd)) = *kptr4;
        *reinterpret_cast<float4*>(&sV_t(nn, dd)) = *vptr4;
      }
    } else {
      int total_pairs = total_elems / 2;
      for (int idx = tid; idx < total_pairs; idx += THREADS) {
        int idx2 = idx * 2;
        int nn = idx2 / D;
        int dd = idx2 - nn * D;
        const half2* kptr2 = reinterpret_cast<const half2*>(&mK(n0 + nn, dd));
        const half2* vptr2 = reinterpret_cast<const half2*>(&mV(n0 + nn, dd));
        *reinterpret_cast<half2*>(&sK_t(nn, dd)) = *kptr2;
        *reinterpret_cast<half2*>(&sV_t(nn, dd)) = *vptr2;
      }
    }
    __syncthreads();
    if (row_valid) {
      float s[BLOCK_N];
      #pragma unroll
      for (int nn = 0; nn < BLOCK_N; ++nn) {
        if (nn >= tile_n) { s[nn] = -INFINITY; continue; }
        float partial = 0.0f;
        int i = 0;
        if ((epl & 7) == 0) {
          for (; i < epl; i += 8) {
            float4 kv4 = *reinterpret_cast<const float4*>(&sK_t(nn, lane * epl + i));
            float4 qv4 = *reinterpret_cast<const float4*>(&q_reg[i]);
            const half2* kv2 = reinterpret_cast<const half2*>(&kv4);
            const half2* qv2 = reinterpret_cast<const half2*>(&qv4);
            #pragma unroll
            for (int j = 0; j < 4; ++j) {
              float2 kf = __half22float2(kv2[j]);
              float2 qf = __half22float2(qv2[j]);
              partial += qf.x * kf.x + qf.y * kf.y;
            }
          }
        } else {
          for (; i + 1 < epl; i += 2) {
            half2 kv = *reinterpret_cast<const half2*>(&sK_t(nn, lane * epl + i));
            half2 qv = *reinterpret_cast<const half2*>(&q_reg[i]);
            float2 kf = __half22float2(kv);
            float2 qf = __half22float2(qv);
            partial += qf.x * kf.x + qf.y * kf.y;
          }
          for (; i < epl; ++i) {
            partial += __half2float(q_reg[i]) * __half2float(sK_t(nn, lane * epl + i));
          }
        }
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
          partial += __shfl_down_sync(0xffffffff, partial, offset);
        }
        partial = __shfl_sync(0xffffffff, partial, 0);
        s[nn] = partial * scale;
      }
      float tile_max = -INFINITY;
      #pragma unroll
      for (int nn = 0; nn < BLOCK_N; ++nn) {
        if (nn < tile_n) tile_max = fmaxf(tile_max, s[nn]);
      }
      float new_max = fmaxf(m_i, tile_max);
      float correction = __expf(m_i - new_max);
      l_i *= correction;
      for (int i = 0; i < epl; ++i) o_reg[i] *= correction;
      #pragma unroll
      for (int nn = 0; nn < BLOCK_N; ++nn) {
        if (nn >= tile_n) continue;
        float p = __expf(s[nn] - new_max);
        l_i += p;
        int i = 0;
        if ((epl & 7) == 0) {
          for (; i < epl; i += 8) {
            float4 vv4 = *reinterpret_cast<const float4*>(&sV_t(nn, lane * epl + i));
            const half2* vv2 = reinterpret_cast<const half2*>(&vv4);
            #pragma unroll
            for (int j = 0; j < 4; ++j) {
              float2 vf = __half22float2(vv2[j]);
              o_reg[i + 2 * j]     += p * vf.x;
              o_reg[i + 2 * j + 1] += p * vf.y;
            }
          }
        } else {
          for (; i + 1 < epl; i += 2) {
            half2 vv = *reinterpret_cast<const half2*>(&sV_t(nn, lane * epl + i));
            float2 vf = __half22float2(vv);
            o_reg[i]   += p * vf.x;
            o_reg[i+1] += p * vf.y;
          }
          for (; i < epl; ++i) {
            o_reg[i] += p * __half2float(sV_t(nn, lane * epl + i));
          }
        }
      }
      m_i = new_max;
    }
    __syncthreads();
  }
  if (row_valid) {
    float inv_l = 1.0f / l_i;
    int i = 0;
    for (; i + 1 < epl; i += 2) {
      half2 val = __floats2half2_rn(o_reg[i] * inv_l, o_reg[i+1] * inv_l);
      *reinterpret_cast<half2*>(&mO(row, lane * epl + i)) = val;
    }
    for (; i < epl; ++i) {
      mO(row, lane * epl + i) = __float2half(o_reg[i] * inv_l);
    }
  }
}

torch::Tensor flash_attention_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
  TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "Q,K,V must be CUDA tensors");
  TORCH_CHECK(Q.scalar_type() == at::kHalf && K.scalar_type() == at::kHalf && V.scalar_type() == at::kHalf,
              "Q,K,V must be float16");
  TORCH_CHECK(Q.dim() == 4 && K.dim() == 4 && V.dim() == 4, "Q,K,V must be [B,H,N,D]");

  auto Qc = Q.contiguous();
  auto Kc = K.contiguous();
  auto Vc = V.contiguous();

  int B = (int)Qc.size(0);
  int H = (int)Qc.size(1);
  int N = (int)Qc.size(2);
  int D = (int)Qc.size(3);

  TORCH_CHECK(D % 32 == 0, "embedding dimension must be divisible by 32");
  TORCH_CHECK(D / 32 <= MAX_EPL, "embedding dimension too large for this kernel");

  auto O = torch::empty_like(Qc);

  float scale = 1.0f / sqrtf((float)D);
  dim3 block(THREADS);
  dim3 grid((N + ROWS_PER_BLOCK - 1) / ROWS_PER_BLOCK, B * H);
  int device_id = 0;
  cudaGetDevice(&device_id);
  int max_smem_optin = 0;
  cudaError_t attr_query_err = cudaDeviceGetAttribute(
      &max_smem_optin, cudaDevAttrMaxSharedMemoryPerBlockOptin, device_id);
  TORCH_CHECK(attr_query_err == cudaSuccess,
              "cudaDeviceGetAttribute(MaxSharedMemoryPerBlockOptin) failed: ",
              cudaGetErrorString(attr_query_err));
  // Derive the largest K/V tile length (<= BLOCK_N) whose shared-memory footprint
  // (2 * block_n * D * sizeof(half)) fits within the device's actual dynamic shared
  // memory limit for this head dimension D. This preserves the tiling/online-softmax
  // structure while bounding shared memory usage across GPUs and head dims.
  size_t bytes_per_row = 2 * (size_t)D * sizeof(half);
  size_t safe_smem_limit = (size_t)max_smem_optin > 1024 ? (size_t)max_smem_optin - 1024 : (size_t)max_smem_optin;
  int block_n = BLOCK_N;
  if (bytes_per_row > 0) {
    size_t max_rows = safe_smem_limit / bytes_per_row;
    if (max_rows < (size_t)block_n) block_n = (int)max_rows;
  }
  TORCH_CHECK(block_n >= 1,
              "embedding dimension too large: cannot fit even a single K/V row (D=", D,
              ") into ", max_smem_optin, " bytes of shared memory");
  size_t smem_bytes = 2 * (size_t)block_n * (size_t)D * sizeof(half);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  int epl_dispatch = D / 32;
#define FLASH_ATTN_LAUNCH_CASE(EPLV)                                                               \
  case EPLV: {                                                                                     \
    auto attr_err = cudaFuncSetAttribute(                                                          \
        flash_attn_kernel<EPLV>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_bytes);     \
    TORCH_CHECK(attr_err == cudaSuccess,                                                           \
                "cudaFuncSetAttribute failed for smem_bytes=", smem_bytes, " (block_n=", block_n, \
                ", D=", D, "): ", cudaGetErrorString(attr_err));                                    \
    flash_attn_kernel<EPLV><<<grid, block, smem_bytes, stream>>>(                                  \
        reinterpret_cast<const half*>(Qc.data_ptr<at::Half>()),                                    \
        reinterpret_cast<const half*>(Kc.data_ptr<at::Half>()),                                    \
        reinterpret_cast<const half*>(Vc.data_ptr<at::Half>()),                                    \
        reinterpret_cast<half*>(O.data_ptr<at::Half>()),                                           \
        B, H, N, D, scale, block_n);                                                                \
    break;                                                                                         \
  }
  switch (epl_dispatch) {
    FLASH_ATTN_LAUNCH_CASE(1)
    FLASH_ATTN_LAUNCH_CASE(2)
    FLASH_ATTN_LAUNCH_CASE(4)
    FLASH_ATTN_LAUNCH_CASE(8)
    FLASH_ATTN_LAUNCH_CASE(16)
    FLASH_ATTN_LAUNCH_CASE(32)
    FLASH_ATTN_LAUNCH_CASE(64)
    default: {
      auto attr_err = cudaFuncSetAttribute(
          flash_attn_kernel<0>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_bytes);
      TORCH_CHECK(attr_err == cudaSuccess,
                  "cudaFuncSetAttribute failed for smem_bytes=", smem_bytes, " (block_n=", block_n,
                  ", D=", D, "): ", cudaGetErrorString(attr_err));
      flash_attn_kernel<0><<<grid, block, smem_bytes, stream>>>(
          reinterpret_cast<const half*>(Qc.data_ptr<at::Half>()),
          reinterpret_cast<const half*>(Kc.data_ptr<at::Half>()),
          reinterpret_cast<const half*>(Vc.data_ptr<at::Half>()),
          reinterpret_cast<half*>(O.data_ptr<at::Half>()),
          B, H, N, D, scale, block_n);
    }
  }
#undef FLASH_ATTN_LAUNCH_CASE
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "flash_attn_kernel launch failed: ", cudaGetErrorString(err));

  return O;
}
"""

flash_attn_ext = load_inline(
    name="cute_flash_attn_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["flash_attention_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = flash_attn_ext

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        return self._ext.flash_attention_forward(Q, K, V)
